from pathlib import Pathimport reimport pytestimport pytest_asynciofrom examples import jira_scenario_IIREQUIRED_ENV_VARS = ("ANTHROPIC_API_KEY", "JIRA_URL", "JIRA_USERNAME", "JIRA_API_TOKEN")OUTPUT_SPEC = Path(__file__).resolve().parents[1] / "output" / "tests" / "greenkart.spec.ts"RUN_FLAG = "RUN_JIRA_SCENARIO_II_TESTS"def _missing_env_vars() -> list[str]:    return [name for name in REQUIRED_ENV_VARS if not jira_scenario_II.os.getenv(name)]@pytest_asyncio.fixture(scope="module")async def generated_playwright_spec() -> str:    if jira_scenario_II.os.getenv(RUN_FLAG, "").lower() != "true":        pytest.skip(f"Set {RUN_FLAG}=true to run live jira_scenario_II integration tests")    missing = _missing_env_vars()    if missing:        pytest.skip(f"Integration test requires env vars: {', '.join(missing)}")    if OUTPUT_SPEC.exists():        OUTPUT_SPEC.unlink()    await jira_scenario_II.main()    assert OUTPUT_SPEC.exists(), "Scenario did not generate output/tests/greenkart.spec.ts"    return OUTPUT_SPEC.read_text(encoding="utf-8")class TestJiraScenarioAgentBehavior:    @pytest.mark.asyncio    async def test_generates_playwright_test_file(self, generated_playwright_spec: str):        assert generated_playwright_spec.strip(), "Generated Playwright spec is empty"    @pytest.mark.asyncio    async def test_generated_spec_has_expected_structure(self, generated_playwright_spec: str):        assert any(            marker in generated_playwright_spec            for marker in ("test(", "expect(", "describe(", "page.")        ), "Generated output does not look like a Playwright test"    @pytest.mark.asyncio    async def test_generated_spec_does_not_hallucinate_non_kan_tickets(self, generated_playwright_spec: str):        mentioned_tickets = re.findall(r"[A-Z]+-\d+", generated_playwright_spec)        for ticket in mentioned_tickets:            assert ticket.startswith("KAN-"), f"Potential hallucinated ticket found: {ticket}"